&lt;div class=&quot;content&quot;&gt;
&lt;img src=&quot;diag-plantuml-md5-a18bd3a0b6ce969345769dc79ff0cd2c.png&quot; alt=&quot;Diagram&quot; width=&quot;478&quot; height=&quot;494&quot;&gt;
&lt;/div&gt;
&lt;/div&gt;
