&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_introduction&quot;&gt;Introduction&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;&lt;em&gt;Target audience :&lt;/em&gt; Intermediate to advanced Kotlin developers.&lt;/div&gt;
&lt;p&gt;In the world of functional programming in Kotlin, the Arrow library provides powerful tools for handling errors and alternative cases. Among these tools, the monad`Either`stands out for its ability to represent two possible states: success (Right) or failure (Left). But how to navigate effectively between these two states? That&amp;#8217;s what we will explore in this article.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_what_is_the_either_monad&quot;&gt;What is the Either monad?&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;The monad`Either`is a data structure that represents two mutually exclusive possibilities. In Kotlin with Arrow, with Arrow, it is often used to handle the success and failure cases of an operation, providing an elegant alternative to traditional exceptions.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_why_use_either&quot;&gt;Why use Either ?&lt;/h3&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;Explicit error handling: Forces the developer to consider failure cases.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Functional composition: Facilitates the chaining of operations that can fail.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Type-safety: Errors are typed, which helps handle them more precisely.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;No exceptions: Avoid side effects and unexpected interruptions of the execution flow.&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_context&quot;&gt;Context&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Let&amp;#8217;s imagine that you are developing a REST API withhttps://spring.io/projects/spring-boot/[Spring Boot,windows=read-later] et &lt;a href=&quot;https://kotlinlang.org/&quot;&gt;Kotlin&lt;/a&gt;, using the libraryhttps://arrow-kt.io/[Arrow,windows=read-later]. You have a function`findOneUserByEmail`who returns a`Either&amp;lt;Throwable, User&amp;gt;`How can you process this result in an elegant and functional way?&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;We have a User class:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-kotlin&quot; data-lang=&quot;kotlin&quot;&gt;@file:Suppress(
    &quot;RemoveRedundantQualifierName&quot;,
    &quot;MemberVisibilityCanBePrivate&quot;,
    &quot;SqlNoDataSourceInspection&quot;
)

package webapp.users

import arrow.core.Either
import arrow.core.left
import arrow.core.right
import com.fasterxml.jackson.annotation.JsonIgnore
import com.fasterxml.jackson.databind.ObjectMapper
import jakarta.validation.constraints.NotNull
import jakarta.validation.constraints.Pattern
import jakarta.validation.constraints.Size
import org.springframework.beans.factory.getBean
import org.springframework.context.ApplicationContext
import org.springframework.data.r2dbc.core.R2dbcEntityTemplate
import org.springframework.r2dbc.core.DatabaseClient
import org.springframework.r2dbc.core.awaitOne
import org.springframework.r2dbc.core.awaitRowsUpdated
import webapp.core.property.ANONYMOUS_USER
import webapp.core.property.EMPTY_STRING
import webapp.core.utils.AppUtils.cleanField
import webapp.users.EntityModel.Companion.ID_MEMBER
import webapp.users.User.UserDao.Attributes.EMAIL_ATTR
import webapp.users.User.UserDao.Attributes.ID_ATTR
import webapp.users.User.UserDao.Attributes.LANG_KEY_ATTR
import webapp.users.User.UserDao.Attributes.LOGIN_ATTR
import webapp.users.User.UserDao.Attributes.PASSWORD_ATTR
import webapp.users.User.UserDao.Attributes.VERSION_ATTR
import webapp.users.User.UserDao.Constraints.LOGIN_REGEX
import webapp.users.User.UserDao.Fields.EMAIL_FIELD
import webapp.users.User.UserDao.Fields.ID_FIELD
import webapp.users.User.UserDao.Fields.LANG_KEY_FIELD
import webapp.users.User.UserDao.Fields.LOGIN_FIELD
import webapp.users.User.UserDao.Fields.PASSWORD_FIELD
import webapp.users.User.UserDao.Fields.VERSION_FIELD
import webapp.users.User.UserDao.Relations.INSERT
import webapp.users.security.Role
import webapp.users.security.Role.RoleDao
import webapp.users.security.UserRole.UserRoleDao
import java.util.*
import jakarta.validation.constraints.Email as EmailConstraint

data class User(
    override val id: UUID? = null,

    @field:NotNull
    @field:Pattern(regexp = LOGIN_REGEX)
    @field:Size(min = 1, max = 50)
    val login: String,

    @JsonIgnore
    @field:NotNull
    @field:Size(min = 60, max = 60)
    val password: String = EMPTY_STRING,

    @field:EmailConstraint
    @field:Size(min = 5, max = 254)
    val email: String = EMPTY_STRING,

    @JsonIgnore
    val roles: MutableSet&amp;lt;Role&amp;gt; = mutableSetOf(Role(ANONYMOUS_USER)),

    @field:Size(min = 2, max = 10)
    val langKey: String = EMPTY_STRING,

    @JsonIgnore
    val version: Long = -1,
) : EntityModel&amp;lt;UUID&amp;gt;() {

    companion object {
        @JvmStatic
        fun main(args: Array&amp;lt;String&amp;gt;) = println(UserDao.Relations.sqlScript)
    }

    object UserDao {
        object Constraints {
            // Regex for acceptable logins
            const val LOGIN_REGEX =
                &quot;^(?&amp;gt;[a-zA-Z0-9!$&amp;amp;*+=?^_`{|}~.-]+@[a-zA-Z0-9-]+(?:\\.[a-zA-Z0-9-]+)*)|(?&amp;gt;[_.@A-Za-z0-9-]+)$&quot;
            const val PASSWORD_MIN: Int = 4
            const val PASSWORD_MAX: Int = 16
            const val IMAGE_URL_DEFAULT = &quot;https://placehold.it/50x50&quot;
            const val PHONE_REGEX = &quot;^(\\+|00)?[1-9]\\d{0,49}\$&quot;
        }

        object Members {
            const val PASSWORD_MEMBER = &quot;password&quot;
            const val ROLES_MEMBER = &quot;roles&quot;
        }

        object Fields {
            const val ID_FIELD = &quot;`id`&quot;
            const val LOGIN_FIELD = &quot;`login`&quot;
            const val PASSWORD_FIELD = &quot;`password`&quot;
            const val EMAIL_FIELD = &quot;`email`&quot;
            const val LANG_KEY_FIELD = &quot;`lang_key`&quot;
            const val VERSION_FIELD = &quot;`version`&quot;
        }

        object Attributes {
            val ID_ATTR = ID_FIELD.cleanField()
            val LOGIN_ATTR = LOGIN_FIELD.cleanField()
            val PASSWORD_ATTR = PASSWORD_FIELD.cleanField()
            val EMAIL_ATTR = EMAIL_FIELD.cleanField()
            const val LANG_KEY_ATTR = &quot;langKey&quot;
            val VERSION_ATTR = VERSION_FIELD.cleanField()
        }

        object Relations {
            const val TABLE_NAME = &quot;`user`&quot;
            const val SQL_SCRIPT = &quot;&quot;&quot;
            CREATE TABLE IF NOT EXISTS $TABLE_NAME (
                $ID_FIELD                     UUID default random_uuid() PRIMARY KEY,
                $LOGIN_FIELD                  VARCHAR,
                $PASSWORD_FIELD               VARCHAR,
                $EMAIL_FIELD                  VARCHAR,
                $LANG_KEY_FIELD               VARCHAR,
                $VERSION_FIELD                bigint
            );
            CREATE UNIQUE INDEX IF NOT EXISTS `uniq_idx_user_login`
            ON $TABLE_NAME ($LOGIN_FIELD);
            CREATE UNIQUE INDEX IF NOT EXISTS `uniq_idx_user_email`
            ON $TABLE_NAME ($EMAIL_FIELD);
&quot;&quot;&quot;

            @Suppress(&quot;SqlDialectInspection&quot;)
            const val INSERT = &quot;&quot;&quot;
            insert into $TABLE_NAME (
                $LOGIN_FIELD, $EMAIL_FIELD,
                $PASSWORD_FIELD, $LANG_KEY_FIELD,
                $VERSION_FIELD
            ) values ( :login, :email, :password, :langKey, :version)&quot;&quot;&quot;

            @JvmStatic
            val sqlScript: String
                get() = setOf(
                    UserDao.Relations.SQL_SCRIPT,
                    RoleDao.Relations.SQL_SCRIPT,
                    UserRoleDao.Relations.SQL_SCRIPT
                ).joinToString(&quot;&quot;)
                    .trimMargin()
        }

        object Dao {
            val Pair&amp;lt;User, ApplicationContext&amp;gt;.toJson: String
                get() = second.getBean&amp;lt;ObjectMapper&amp;gt;().writeValueAsString(first)

            suspend fun Pair&amp;lt;User, ApplicationContext&amp;gt;.save(): Either&amp;lt;Throwable, Long&amp;gt; = try {
                second.getBean&amp;lt;R2dbcEntityTemplate&amp;gt;()
                    .databaseClient
                    .sql(INSERT)
                    .bind(LOGIN_ATTR, first.login)
                    .bind(EMAIL_ATTR, first.email)
                    .bind(PASSWORD_ATTR, first.password)
                    .bind(LANG_KEY_ATTR, first.langKey)
                    .bind(VERSION_ATTR, first.version)
                    .fetch()
                    .awaitRowsUpdated()
                    .right()
            } catch (e: Throwable) {
                e.left()
            }


            suspend fun ApplicationContext.findOneUserByEmail(
                email: String
            ): Either&amp;lt;Throwable, User&amp;gt; = try {
                getBean&amp;lt;DatabaseClient&amp;gt;()
                    .sql(&quot;SELECT * FROM `user` WHERE LOWER(email) = LOWER(:email)&quot;)
                    .bind(&quot;email&quot;, email)
                    .fetch()
                    .awaitOne()
                    .let { row -&amp;gt;
                        User(
                            id = row[ID_ATTR] as UUID?,
                            login = row[LOGIN_ATTR] as String,
                            password = row[PASSWORD_ATTR] as String,
                            email = row[EMAIL_ATTR] as String,
                            langKey = row[LANG_KEY_ATTR] as String,
                            version = row[VERSION_ATTR] as Long
                        )
                    }.right()
            } catch (e: Throwable) {
                e.left()
            }
        }
    }

    /** Account REST API URIs */
    object UserRestApis {
        const val API_AUTHORITY = &quot;/api/authorities&quot;
        const val API_USERS = &quot;/api/users&quot;
        const val API_SIGNUP = &quot;/signup&quot;
        const val API_SIGNUP_PATH = &quot;$API_USERS$API_SIGNUP&quot;
        const val API_ACTIVATE = &quot;/activate&quot;
        const val API_ACTIVATE_PATH = &quot;$API_USERS$API_ACTIVATE?key=&quot;
        const val API_ACTIVATE_PARAM = &quot;{activationKey}&quot;
        const val API_ACTIVATE_KEY = &quot;key&quot;
        const val API_RESET_INIT = &quot;/reset-password/init&quot;
        const val API_RESET_FINISH = &quot;/reset-password/finish&quot;
        const val API_CHANGE = &quot;/change-password&quot;
        const val API_CHANGE_PATH = &quot;$API_USERS$API_CHANGE&quot;
    }
}

// Abstract entity model with Generic ID, which can be of any type
abstract class EntityModel&amp;lt;T&amp;gt;(
    open val id: T? = null
) {
    companion object {
        const val ID_MEMBER = &quot;id&quot;
    }
}

// Generic extension function that allows the ID to be applied to any EntityModel type
inline fun &amp;lt;reified T : EntityModel&amp;lt;ID&amp;gt;, ID&amp;gt; T.withId(id: ID): T {
    // Use reflection to create a copy with the passed ID
    return this::class.constructors.first { it.parameters.any { param -&amp;gt; param.name == ID_MEMBER } }
        .call(id, *this::class.constructors.first().parameters.drop(1).map { param -&amp;gt;
            this::class.members.first { member -&amp;gt; member.name == param.name }.call(this)
        }.toTypedArray())
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_the_different_approaches&quot;&gt;The different approaches&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_the_classic_approach_with_when&quot;&gt;The classic approach with `when&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-kotlin&quot; data-lang=&quot;kotlin&quot;&gt;val user: User by lazy { userFactory(USER) }

val result: Either&amp;lt;Throwable, User&amp;gt; = context.findOneUserByEmail(user.email)

when (result) {
    is Either.Left -&amp;gt; {
        val error = result.value
        println(&quot;Erreur : ${error.message}&quot;)
    }
    is Either.Right -&amp;gt; {
        val user = result.value
        println(&quot;Utilisateur trouvé : ${user.login}&quot;)
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;This method, while simple and readable, does not fully take advantage of Arrow&amp;#8217;s functional capabilities.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_use_of_fold_for_a_more_concise_approach&quot;&gt;Use of &lt;code&gt;fold&lt;/code&gt; for a more concise approach&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-kotlin&quot; data-lang=&quot;kotlin&quot;&gt;result.fold(
{ error -&amp;gt; println(&quot;Erreur : ${error.message}&quot;) },
{ user -&amp;gt; println(&quot;Utilisateur trouvé : ${user.login}&quot;) }
)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;`fold`allows defining actions for both cases (Left and Right) in a concise and elegant manner.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_transformation_with_map_and_mapleft&quot;&gt;Transformation with &lt;code&gt;map&lt;/code&gt; and `mapLeft&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-kotlin&quot; data-lang=&quot;kotlin&quot;&gt;val processedResult = result
    .map { user -&amp;gt; &quot;Utilisateur trouvé : ${user.login}&quot; }
    .mapLeft { error -&amp;gt; &quot;Erreur : ${error.message}&quot; }

println(processedResult.merge())&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;This approach allows transforming the values contained in Either while preserving its structure, ideal for more complex processing chains.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_error_handling_with_getorelse&quot;&gt;Error handling with `getOrElse&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-kotlin&quot; data-lang=&quot;kotlin&quot;&gt;val user = result.getOrElse { error -&amp;gt;
    println(&quot;Erreur : ${error.message}&quot;)
    User(login = &quot;default&quot;, email = &quot;default@example.com&quot;) // utilisateur par défaut
}
println(&quot;Login : ${user.login}&quot;)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;`getOrElse`offers elegant error handling by allowing a default value to be provided&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_side_actions_with_onleft_and_onright&quot;&gt;Side actions with &lt;code&gt;onLeft&lt;/code&gt; and `onRight&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-kotlin&quot; data-lang=&quot;kotlin&quot;&gt;result.onLeft { error -&amp;gt; println(&quot;Erreur : ${error.message}&quot;) }
.onRight { user -&amp;gt; println(&quot;Utilisateur trouvé : ${user.login}&quot;) }&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;These methods allow performing actions on each side without modifying the Either, perfect for logging or light side effects.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_chaining_operations_with_flatmap&quot;&gt;Chaining operations with `flatMap&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-kotlin&quot; data-lang=&quot;kotlin&quot;&gt;fun findUser(email: String): Either&amp;lt;Throwable, User&amp;gt; = // ... implémentation

fun getUserPermissions(user: User): Either&amp;lt;Throwable, List&amp;lt;String&amp;gt;&amp;gt; = // ... implémentation

val userPermissions = findUser(&quot;user@example.com&quot;)
    .flatMap { user -&amp;gt; getUserPermissions(user) }&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;code&gt;flatMap`is useful for chaining operations that themselves return`Either&lt;/code&gt;, thus avoiding the`Either`nested.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_bidirectional_transformation_with_bimap&quot;&gt;Bidirectional transformation with `bimap&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-kotlin&quot; data-lang=&quot;kotlin&quot;&gt;val result: Either&amp;lt;Throwable, User&amp;gt; = // ... obtention du résultat
val processedResult = result.bimap(
    { error -&amp;gt; &quot;Erreur: ${error.message}&quot; },
    { user -&amp;gt; &quot;Utilisateur: ${user.login}&quot; }
)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;`bimap`allows to transform both the left side and the right side in a single operation.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_swapping_the_sides_with_swap&quot;&gt;Swapping the sides with `swap&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-kotlin&quot; data-lang=&quot;kotlin&quot;&gt;val result: Either&amp;lt;Throwable, User&amp;gt; = // ... obtention du résultat
val swapped = result.swap()&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;code&gt;swap`is useful when you want to reverse the sides of a`Either&lt;/code&gt;, for example to adapt the interface of a function to another.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_usage_of_tap_and_tapleft&quot;&gt;Usage of &lt;code&gt;tap&lt;/code&gt; and &lt;code&gt;tapLeft&lt;/code&gt; :&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-kotlin&quot; data-lang=&quot;kotlin&quot;&gt;result.tap { user -&amp;gt; println(&quot;Utilisateur trouvé : ${user.login}&quot;) }
.tapLeft { error -&amp;gt; println(&quot;Erreur : ${error.message}&quot;) }&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Similar to`onLeft` et &lt;code&gt;onRight&lt;/code&gt;, but these methods return the original Either, which is useful for chaining operations.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_use_of_recover&quot;&gt;Use of &lt;code&gt;recover&lt;/code&gt; :&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-kotlin&quot; data-lang=&quot;kotlin&quot;&gt;val recoveredUser = result.recover { error -&amp;gt;
    println(&quot;Erreur récupérée : ${error.message}&quot;)
    User(login = &quot;recovered&quot;, email = &quot;recovered@example.com&quot;)
}
println(&quot;Login : ${recoveredUser.login}&quot;)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;This method allows converting an Either.Left into an Either.Right by providing a replacement value.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_practical_use_cases&quot;&gt;practical use cases&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Use`fold`for simple operations requiring processing for each case. - Préférez &lt;code&gt;map&lt;/code&gt; et &lt;code&gt;mapLeft`for data transformations without changing the structure of l&#39;`Either&lt;/code&gt;. Opt for`flatMap`when chaining operations that can fail Employ`recover`to provide a default value in case of error. - Choose`onLeft` et &lt;code&gt;onRight&lt;/code&gt; (ou &lt;code&gt;tap&lt;/code&gt; et &lt;code&gt;tapLeft&lt;/code&gt;) for side effects like logging. - Use`bimap`to transform both sides into a single operation. - Apply`swap`when you need to adapt the interface of one function to another.&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_conclusion&quot;&gt;Conclusion&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Each of these approaches has its advantages according to the context of use. Methods like`fold`, &lt;code&gt;map&lt;/code&gt;/&lt;code&gt;mapLeft&lt;/code&gt;, et `recover`are particularly useful when you want to chain several operations or transform the data functionally.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;The monad`Either`Arrow offers remarkable flexibility for handling success and error cases in your Kotlin applications. By mastering these different approaches, you will be able to write code that is more robust, more readable, and more functional.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;In your next project, don&amp;#8217;t hesitate to explore these techniques to get the most out of functional programming with Kotlin and Arrow!&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_to_go_further&quot;&gt;To go further&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Official Arrow documentation:https://arrow-kt.io/docs/apidocs/arrow-core/arrow.core/-either/[Flèche soit] - Kotlin Coroutines with Arrow:https://arrow-kt.io/docs/fx/[Arrow Fx Coroutines]&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Don&amp;#8217;t forget to share your experiences and your favorite techniques for working with`Either`in the comments below!&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Sommaire&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_introduction&quot;&gt;Introduction&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_using_the_find_command&quot;&gt;Using the &lt;code&gt;find&lt;/code&gt; command&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_additional_options_for_find&quot;&gt;Additional options for `find&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_using_the_locate_command&quot;&gt;Using the &lt;code&gt;locate&lt;/code&gt; command&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_using_the_grep_command_to_search_for_text_in_files&quot;&gt;Using the &lt;code&gt;grep&lt;/code&gt; command to search for text in files&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_conclusion&quot;&gt;Conclusion&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_introduction&quot;&gt;Introduction&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;The problem : Search for files in a Linux operating system through the terminal.&lt;/div&gt;
&lt;p&gt;In this article, we will explore how to search for a file on Ubuntu using a Zsh terminal. Zsh (Z shell) is a powerful command interpreter widely used for its flexibility and advanced features.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Ubuntu, a popular Linux distribution, offers several command-line tools for searching files. We will see how to use commands such as`find`, &lt;code&gt;locate&lt;/code&gt; et `grep`to locate files quickly and efficiently in the terminal.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_using_the_find_command&quot;&gt;Using the &lt;code&gt;find&lt;/code&gt; command&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;The command`find`allows to search for files in a specific directory and its subdirectories. Its basic syntax is as follows:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-bash&quot; data-lang=&quot;bash&quot;&gt;find [chemin] -name [nom_du_fichier]&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Here is a practical example where we search for a file named`example.txt`in the directory`/home`(nothing)&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-bash&quot; data-lang=&quot;bash&quot;&gt;find /home -name &quot;example.txt&quot;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;This command will traverse all subdirectories of`/home`and display the full path of the file if it is found.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Online manual of the command`find`:https://man.archlinux.org/man/find.1.fr/[man find,windows=read-later]*&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_additional_options_for_find&quot;&gt;Additional options for `find&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;The command`find`is very powerful and has many options. Here are some useful examples:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Search by file type&lt;/strong&gt;: To search only for files, use`-type f`, and to search directories, use`-type d`. - &lt;strong&gt;Search by size&lt;/strong&gt;You can also filter files based on their size using the option`-size`. Par exemple, pour rechercher des fichiers de plus de 100 Mo, utilisez :&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-bash&quot; data-lang=&quot;bash&quot;&gt;find /home -size +100M&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_using_the_locate_command&quot;&gt;Using the &lt;code&gt;locate&lt;/code&gt; command&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;The command`locate`is faster than`find`because it uses a pre-indexed database of the files present on the system. You must first update this database with the following command:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-bash&quot; data-lang=&quot;bash&quot;&gt;sudo updatedb&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Then you can search for a file like this:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-bash&quot; data-lang=&quot;bash&quot;&gt;locate example.txt&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;I usehttps://fr.wikipedia.org/wiki/Z_Shell[zsh]withhttps://github.com/ohmyzsh/ohmyzsh/wiki[oh-my-zsh], it turns out that the command`locate`is not accessible from`zsh`but quite possible since`bash`, to counter that, the argument`-c`of the command`bash`allows to launch a command`bash`from another type of terminal.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;here I am looking for the files that ends with the pattern`001.pdf`in the user directory&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-bash&quot; data-lang=&quot;bash&quot;&gt;bash -c &quot;locate ~/*001.pdf&quot;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Online manual of the command`locate`:https://man.archlinux.org/man/locate.1.fr/[man locate,windows=read-later]&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_using_the_grep_command_to_search_for_text_in_files&quot;&gt;Using the &lt;code&gt;grep&lt;/code&gt; command to search for text in files&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;If you want to search for specific text inside a file, you can use`grep`. For example, to search for the occurrence of the word &quot;Ubuntu&quot; in all files`.txt`of the current directory, use:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-bash&quot; data-lang=&quot;bash&quot;&gt;grep &quot;Ubuntu&quot; *.txt&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_conclusion&quot;&gt;Conclusion&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Searching for files on Ubuntu via a Zsh terminal can be done using several powerful tools.`find`is flexible and offers a multitude of options, while`locate`allows a quick search using a pre-built database. Finally,`grep`allows finding occurrences of text inside the files.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;These commands offer you a full range of tools to make your file searches more efficient and tailored to your needs, and each of these commands has a manual visible with the command`man`&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Sommaire&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_the_keyboard&quot;&gt;The keyboard:&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_the_ctrl&quot;&gt;&lt;em&gt;the &amp;lt;Ctrl&amp;gt;&lt;/em&gt;&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_permissionauthorization&quot;&gt;Permission(authorization)&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_search_for_files&quot;&gt;Search for files&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_the_keyboard&quot;&gt;The keyboard:&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_the_ctrl&quot;&gt;&lt;em&gt;the &amp;lt;Ctrl&amp;gt;&lt;/em&gt;&lt;/h3&gt;
&lt;table class=&quot;tableblock frame-all grid-all stretch&quot;&gt;
&lt;/table&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;a href=&quot;https://korben.info/les-raccourcis-clavier-pour-bash-terminal-linux-et-macos.html&quot;&gt;link&lt;/a&gt;&lt;br&gt;
&lt;a href=&quot;https://blogmotion.fr/systeme/astuces-bash-linux-16175&quot;&gt;other link&lt;/a&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_permissionauthorization&quot;&gt;Permission(authorization)&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;CHMOD is used to change the permissions of a file.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;PERMISSION      COMMAND&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;U   G   W rwx rwx rwx     chmod 777 filename rwx rwx r-x     chmod 775 filename rwx r-x r-x     chmod 755 filename rw- rw- r--     chmod 664 filename rw- r-- r--     chmod 644 filename&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;U = User G = Group W = World&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;r = Readable w = writable x = executable - = no permission&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Another way to see the permissions:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;400     read by owner 040     read by group 004     read by anybody (other) 200 written by owner 020     write by group 002     written by anyone 100     execute by owner 010     execute by group 001     execute by anybody&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;To obtain a combination, just add them.&lt;br&gt;
For example, to be read, written, executed by the owner,&lt;br&gt;
read, executed, by group and executed by anyone&lt;br&gt;
you would add 400+200+100+040+010+001 to give 751.&lt;br&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_search_for_files&quot;&gt;&lt;a href=&quot;/blog/2024/0074_seach_file_linux_post.html&quot;&gt;Search for files&lt;/a&gt;&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;

&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;preamble&quot;&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;&lt;em&gt;Reading time: 3 min&lt;/em&gt; Pandoc is a universal document converter&lt;/div&gt;
&lt;p&gt;Pandoc is an open source word processing software that can be used to convert documents between different formats. There are several ways to install Pandoc.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_installation_from_the_download_page&quot;&gt;&lt;strong&gt;Installation from the download page&lt;/strong&gt;&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;To install Pandoc from the download page, proceed as follows:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;Go to the Pandoc download page:https://pandoc.org/installing.html/[&lt;a href=&quot;https://pandoc.org/installing.html&quot; class=&quot;bare&quot;&gt;https://pandoc.org/installing.html&lt;/a&gt;]&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Download the package installer for your operating system.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Run the installer to install Pandoc.&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Installation from a zip file&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;To install Pandoc from a zip file, proceed as follows:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;Download the zip file containing the Pandoc binaries and the documentation.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Unzip the zip file.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Move the binaries to a directory of your choice.&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Installation using Chocolatey&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;To install Pandoc using Chocolatey, proceed as follows:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;Open a command prompt.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Run the following command:&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-powershell&quot; data-lang=&quot;powershell&quot;&gt;choco install pandoc&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Installation using winget&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;To install Pandoc using winget, follow these steps:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;Open a command prompt.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Execute the following command:&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-powershell&quot; data-lang=&quot;powershell&quot;&gt;winget install --source winget --exact --id JohnMacFarlane.Pandoc&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Recommendations&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;By default, Pandoc creates PDFs using LaTeX. It is recommended to install LaTeX via MiKTeX. With the option`--pdf-engine`, you can however specify other programs for this task.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Warning&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Using multiple installation methods can result in two separate installations of Pandoc. It is recommended to properly uninstall Pandoc before switching to an alternative installation method.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Installation on Linux via WSL&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Check if the version of pandoc in your package manager is not outdated. Pandoc is located in the repositories of Debian, Ubuntu, Slackware, Arch, Fedora, NixOS, openSUSE, Gentoo, and Void.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;To get the latest version, we offer a binary package for the amd64 architecture on the download page.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;The executable is statically linked and has no dynamic dependencies nor dependencies on external data files. Note: due to static linking, the pandoc binary in this package cannot use Lua filters that require external Lua modules written in C.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;A tarball and a deb installer are provided. To install the deb :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-bash&quot; data-lang=&quot;bash&quot;&gt;sudo dpkg -i $DEB&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Example at the time of writing:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-bash&quot; data-lang=&quot;bash&quot;&gt;wget https://github.com/jgm/pandoc/releases/download/3.1.11.1/pandoc-3.1.11.1-1-amd64.deb&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-bash&quot; data-lang=&quot;bash&quot;&gt;sudo dpkg -i pandoc-3.1.11.1-1-amd64.deb&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;où `$DEB`is the path to the downloaded deb. This will install the executable`pandoc`and the manual page.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;If you are using an RPM-based distribution, you may be able to install the .deb from our download page using alien.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;On any distribution, you can install from the tarball in`$DEST`(for example,&lt;code&gt;/usr/local/&lt;/code&gt; ou &lt;code&gt;$HOME/.local&lt;/code&gt;) by doing :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-bash&quot; data-lang=&quot;bash&quot;&gt;tar xvzf $TGZ --strip-components 1 -C $DEST&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;où `$TGZ`is the path to the downloaded zipped tarball. For Pandoc versions prior to 2.0, which do not provide a tarball, try instead:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-bash&quot; data-lang=&quot;bash&quot;&gt;ar p $DEB data.tar.gz | tar xvz --strip-components 2 -C $DEST&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;You can also install from source, using the instructions below under`Compilation à partir de la source`. Note that most distributions have the Haskell platform in their package repositories. For example, on Debian/Ubuntu, you can install it with&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-bash&quot; data-lang=&quot;bash&quot;&gt;apt-get install haskell-platform&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;By default, Pandoc creates PDFs using LaTeX. We recommend that you install TeX Live via your package manager. (On Debian/Ubuntu,&lt;code&gt;apt-get install texlive&lt;/code&gt;). With the option`--pdf-engine`, you can however specify other programs for this task.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;preamble&quot;&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;&lt;em&gt;Reading time : 2 min&lt;/em&gt; Create a complete implementation of the kotlin.Triple class in JavaScript, TypeScript, and Python using functional programming.&lt;/div&gt;
&lt;p&gt;&lt;strong&gt;Note:&lt;/strong&gt;The types`Maybe`, &lt;code&gt;Either&lt;/code&gt;, `Result`are not part of the core language in JavaScript or TypeScript, so we need to implement them ourselves.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_javascript&quot;&gt;JavaScript&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-javascript&quot; data-lang=&quot;javascript&quot;&gt;//javascript
// Maybe type
const Maybe = (value) =&amp;gt; ({
  map: (fn) =&amp;gt; (value !== null &amp;amp;&amp;amp; value !== undefined ? Maybe(fn(value)) : Maybe(null)),
  flatMap: (fn) =&amp;gt; (value !== null &amp;amp;&amp;amp; value !== undefined ? fn(value) : Maybe(null)),
  getOrElse: (defaultValue) =&amp;gt; (value !== null &amp;amp;&amp;amp; value !== undefined ? value : defaultValue),
});

// Either type
const Either = {
  Left: (value) =&amp;gt; ({
    map: (fn) =&amp;gt; Either.Left(value),
    flatMap: (fn) =&amp;gt; Either.Left(value),
    getOrElse: (defaultValue) =&amp;gt; defaultValue,
    isLeft: true,
    isRight: false,
  }),
  Right: (value) =&amp;gt; ({
    map: (fn) =&amp;gt; Either.Right(fn(value)),
    flatMap: (fn) =&amp;gt; fn(value),
    getOrElse: (defaultValue) =&amp;gt; value,
    isLeft: false,
    isRight: true,
  }),
};

// Triple class
class Triple {
  constructor(a, b, c) {
    this.a = a;
    this.b = b;
    this.c = c;
  }

  map(fn) {
    return new Triple(fn(this.a), fn(this.b), fn(this.c));
  }

  static of(a, b, c) {
    return new Triple(a, b, c);
  }

  // Example method using Maybe and Either
  divideBy(other) {
    return Maybe(this.b)
      .flatMap((numerator) =&amp;gt;
        Maybe(other)
          .flatMap((denominator) =&amp;gt;
            denominator !== 0
              ? Either.Right(numerator / denominator)
              : Either.Left(&#39;Division by zero&#39;)
          )
      )
      .getOrElse(Either.Left(&#39;Invalid input&#39;));
  }
}

// Example usage
const triple = Triple.of(1, 2, 3);
const result = triple.map((x) =&amp;gt; x * 2);
console.log(result); // Triple { a: 2, b: 4, c: 6 }

const divisionResult = triple.divideBy(2);
console.log(divisionResult); // Either.Right { value: 1 }

const invalidDivisionResult = triple.divideBy(0);
console.log(invalidDivisionResult); // Either.Left { value: &#39;Division by zero&#39; }&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_no_text_provided_to_translate&quot;&gt;(No text provided to translate.)&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-typescript&quot; data-lang=&quot;typescript&quot;&gt;//Typescript
// Maybe type
// noinspection JSAnnotator

type Maybe&amp;lt;T&amp;gt; = {
  map&amp;lt;U&amp;gt;(fn: (value: T) =&amp;gt; U): Maybe&amp;lt;U&amp;gt;;
  flatMap&amp;lt;U&amp;gt;(fn: (value: T) =&amp;gt; Maybe&amp;lt;U&amp;gt;): Maybe&amp;lt;U&amp;gt;;
  getOrElse(defaultValue: T): T;
};

const just = &amp;lt;T&amp;gt;(value: T): Maybe&amp;lt;T&amp;gt; =&amp;gt; ({
  map: &amp;lt;U&amp;gt;(fn: (value: T) =&amp;gt; U) =&amp;gt; just(fn(value)),
  flatMap: &amp;lt;U&amp;gt;(fn: (value: T) =&amp;gt; Maybe&amp;lt;U&amp;gt;) =&amp;gt; fn(value),
  getOrElse: (_: T) =&amp;gt; value,
});

const nothing = &amp;lt;T&amp;gt;(): Maybe&amp;lt;T&amp;gt; =&amp;gt; ({
  map: &amp;lt;U&amp;gt;(_: (value: T) =&amp;gt; U) =&amp;gt; nothing&amp;lt;U&amp;gt;(),
  flatMap: &amp;lt;U&amp;gt;(_: (value: T) =&amp;gt; Maybe&amp;lt;U&amp;gt;) =&amp;gt; nothing&amp;lt;U&amp;gt;(),
  getOrElse: (defaultValue: T) =&amp;gt; defaultValue,
});

// Either type
type Either&amp;lt;L, R&amp;gt; = {
  map&amp;lt;U&amp;gt;(fn: (value: R) =&amp;gt; U): Either&amp;lt;L, U&amp;gt;;
  flatMap&amp;lt;U&amp;gt;(fn: (value: R) =&amp;gt; Either&amp;lt;L, U&amp;gt;): Either&amp;lt;L, U&amp;gt;;
  getOrElse(defaultValue: R): R;
  isLeft: boolean;
  isRight: boolean;
};

const left = &amp;lt;L, R&amp;gt;(value: L): Either&amp;lt;L, R&amp;gt; =&amp;gt; ({
  map: &amp;lt;U&amp;gt;(_: (value: R) =&amp;gt; U) =&amp;gt; left&amp;lt;L, U&amp;gt;(value),
  flatMap: &amp;lt;U&amp;gt;(_: (value: R) =&amp;gt; Either&amp;lt;L, U&amp;gt;) =&amp;gt; left&amp;lt;L, U&amp;gt;(value),
  getOrElse: (defaultValue: R) =&amp;gt; defaultValue,
  isLeft: true,
  isRight: false,
});

const right = &amp;lt;L, R&amp;gt;(value: R): Either&amp;lt;L, R&amp;gt; =&amp;gt; ({
  map: &amp;lt;U&amp;gt;(fn: (value: R) =&amp;gt; U) =&amp;gt; right&amp;lt;L, U&amp;gt;(fn(value)),
  flatMap: &amp;lt;U&amp;gt;(fn: (value: R) =&amp;gt; Either&amp;lt;L, U&amp;gt;) =&amp;gt; fn(value),
  getOrElse: (_: R) =&amp;gt; value,
  isLeft: false,
  isRight: true,
});

// Triple class
class Triple&amp;lt;T&amp;gt; {
  constructor(public a: T, public b: T, public c: T) {}

  map&amp;lt;U&amp;gt;(fn: (value: T) =&amp;gt; U): Triple&amp;lt;U&amp;gt; {
    return new Triple&amp;lt;U&amp;gt;(fn(this.a), fn(this.b), fn(this.c));
  }

  static of&amp;lt;T&amp;gt;(a: T, b: T, c: T): Triple&amp;lt;T&amp;gt; {
    return new Triple&amp;lt;T&amp;gt;(a, b, c);
  }

  // Example method using Maybe and Either
  divideBy(other: T): Either&amp;lt;string, number&amp;gt; {
    return just(this.b)
      .flatMap((numerator) =&amp;gt;
        just(other)
          .flatMap((denominator) =&amp;gt;
            denominator !== 0 ? right(numerator / denominator) : left(&#39;Division by zero&#39;)
          )
      )
      .getOrElse(left(&#39;Invalid input&#39;));
  }
}

// Example usage
const triple = Triple.of(1, 2, 3);
const result = triple.map((x) =&amp;gt; x * 2);
console.log(result); // Triple { a: 2, b: 4, c: 6 }

const divisionResult = triple.divideBy(2);
console.log(divisionResult); // Either.Right { value: 1 }

const invalidDivisionResult = triple.divideBy(0);
console.log(invalidDivisionResult); // Either.Left { value: &#39;Division by zero&#39; }&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_python_pydantic_pymonad&quot;&gt;Python, pydantic, pymonad&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;To create a Python implementation using`pydantic`for the validation of types and`pymonad`for the monads:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Install the dependencies:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-bash&quot; data-lang=&quot;bash&quot;&gt;pip install pydantic pymonad&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-python&quot; data-lang=&quot;python&quot;&gt;from pymonad.either import Either, Left, Right
from pydantic import BaseModel, ValidationError, validator

# Définition de la classe Triple avec Pydantic
class Triple(BaseModel):
    a: int
    b: int
    c: int

    @validator(&#39;b&#39;)
    def validate_b(cls, b, values):
        if b == 0:
            raise ValueError(&#39;Division by zero is not allowed&#39;)
        return b

    # Méthode utilisant Either pour la gestion des erreurs
    def divide_by(self, other):
        def division(numerator, denominator):
            return Right(numerator / denominator)

        def handle_error(error):
            return Left(str(error))

        return Either(lambda: division(self.b, other)).or_else(handle_error)

# Exemple d&#39;utilisation
try:
    triple = Triple(a=1, b=2, c=3)
    result = triple.divide_by(2)

    if result.is_right:
        print(f&#39;Division result: {result.value}&#39;)
    else:
        print(f&#39;Error: {result.value}&#39;)

except ValidationError as e:
    print(f&#39;Validation Error: {e}&#39;)
except Exception as e:
    print(f&#39;An unexpected error occurred: {e}&#39;)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;div class=&quot;title&quot;&gt;In this example:&lt;/div&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;pydantic`to define the class`Triple`with typed fields. The method`divide_by`uses the monad`Either&lt;/code&gt; de `pymonad`to handle potential errors resulting from division by zero. - Custom validation to ensure that the value of`b`is not equal to zero. If it is equal to zero, an exception is raised, and`pymonad`capture this exception to return a result`Left`indicating the error.&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

