      &amp;lt;div class=&quot;flexbox&quot;&amp;gt;
        &amp;lt;h2&amp;gt;Flexbox&amp;lt;/h2&amp;gt;
        &amp;lt;ul&amp;gt;
          &amp;lt;li&amp;gt;boite 1&amp;lt;/li&amp;gt;
